export type CatWho = "a" | "b";
export type CatPose = "sit" | "walk" | "meow" | "bat" | "loaf" | "chair" | "roll" | "lie" | "belly" | "groom" | "stand" | "perch";
export type CatPropName = "yarn" | "mouse" | "fish" | "wand" | "bowl";
export type CatSpriteSize = 48 | 32;

export interface CatWalk { readonly steps: readonly number[]; readonly ms: number; readonly glide: boolean }

export interface CatSpriteSet {
  readonly W: number;
  readonly H: number;
  readonly cats: { readonly [W in CatWho]: { readonly [P in CatPose]?: readonly string[] } };
  readonly walk: { readonly [W in CatWho]: CatWalk };
  readonly chair: string;
  readonly arm: readonly [number, number];
  readonly props: { readonly [P in CatPropName]: { readonly frames: readonly string[] } };
}

export interface CatSpriteFrame { readonly x: number; readonly y: number; readonly w: number; readonly h: number; readonly px: Uint8Array }

export function decodeCatFrame(code: string): CatSpriteFrame {
  const colon = code.indexOf(":");
  const [x, y, w] = code.slice(0, colon).split(",").map(Number);
  const rows = code.slice(colon + 1).split("/");
  const px = new Uint8Array(w * rows.length);
  rows.forEach((row, j) => {
    let i = 0;
    for (const [, count, ch] of row.matchAll(/(\d*)([.A-Z])/g)) {
      const n = count ? Number(count) : 1;
      if (ch !== ".") px.fill(ch.charCodeAt(0) - 64, j * w + i, j * w + i + n);
      i += n;
    }
  });
  return { x, y, w, h: rows.length, px };
}

